// Get returns the record addressed by its resource name.
func (r *GraphQLHotelRepository) Get(ctx context.Context, name string) (*hotelv1.Hotel, error) {
	ids, err := repox.SplitName(name, "hotels")
	if err != nil {
		return nil, err
	}
	return r.get(ctx, ids[len(ids)-1])
}

// rowID returns the surrogate key of the row named name: its bare id.
func (r *GraphQLHotelRepository) rowID(_ context.Context, name string) (string, error) {
	ids, err := repox.SplitName(name, "hotels")
	if err != nil {
		return "", err
	}
	return ids[len(ids)-1], nil
}

// get loads by surrogate key — the private read every generated method
// re-reads through.
func (r *GraphQLHotelRepository) get(ctx context.Context, id string) (*hotelv1.Hotel, error) {
	row, err := r.Svc.Query.Hotel.Resource.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	return r.toProto(ctx, row, nil)
}

