// newInput builds the insert a Batch queues for in, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLHotelRepository) newInput(in *hotelv1.Hotel) (resourceql.CreateInput, *hotelv1.Hotel, error) {
	var ci resourceql.CreateInput
	id := repox.NewULID()
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "hotels")
		if err != nil {
			return ci, nil, err
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*hotelv1.Hotel)
	in.Name = FormatHotelName(id)
	ci = hotelToCreateInput(in)
	ci.Id = id
	ci.Etag = repox.NewULID()
	now := tsToStr(timestamppb.New(time.Now().UTC()))
	ci.CreateTime = now
	ci.UpdateTime = now
	return ci, in, nil
}

