// UpdateOutputOnly persists the server-owned fields of in that paths names.
// When in.Etag is set the write is guarded server-side, as in Update.
func (r *GraphQLHotelRepository) UpdateOutputOnly(ctx context.Context, in *hotelv1.Hotel, paths []string) (*hotelv1.Hotel, error) {
	if len(paths) == 0 {
		return nil, fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument)
	}
	id, err := r.rowID(ctx, in.GetName())
	if err != nil {
		return nil, err
	}
	patch := hotelToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	if in.GetEtag() != "" {
		if _, err := r.Svc.Mutation.Hotel.Resource.UpdateIfMatch(ctx, id, patch, resourceql.Etag.Eq(in.GetEtag())); err != nil {
			return nil, mapGraphQLErr(err)
		}
		return r.get(ctx, id)
	}
	resp, err := r.Svc.Mutation.Hotel.Resource.Update(ctx, id, patch)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return nil, repox.ErrNotFound
	}
	return r.get(ctx, id)
}

// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays. The update time is set to the same instant: the
// delete is the record's latest write, which a reader by update time can tell
// from any write after it.
func (r *GraphQLHotelRepository) Delete(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "hotels"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	if _, err := r.Svc.Mutation.Hotel.Resource.UpdateIfMatch(ctx, id, r.deletePatch(), resourceql.DeleteTime.IsNull(true)); err != nil {
		if errors.Is(err, graphql.ErrConflict) {
			return repox.ErrNotFound
		}
		return mapGraphQLErr(err)
	}
	return nil
}

// deletePatch is the write that soft-deletes a record now: Delete's, and a
// Batch's.
func (r *GraphQLHotelRepository) deletePatch() resourceql.UpdateInput {
	at := time.Now().UTC()
	now := at.Format(time.RFC3339Nano)
	patch := resourceql.UpdateInput{DeleteTime: graphql.Value(now)}
	patch.UpdateTime = graphql.Value(now) // the delete is the record's latest write
	if r.Retention > 0 {
		patch.ExpireTime = graphql.Value(at.Add(r.Retention).Format(time.RFC3339Nano))
	}
	patch.Etag = graphql.Value(repox.NewULID())
	return patch
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GraphQLHotelRepository) Undelete(ctx context.Context, name string) (*hotelv1.Hotel, error) {
	id, err := r.rowID(ctx, name)
	if err != nil {
		return nil, err
	}
	patch := resourceql.UpdateInput{DeleteTime: graphql.Null[string]()}
	patch.UpdateTime = graphql.Value(time.Now().UTC().Format(time.RFC3339Nano))
	patch.ExpireTime = graphql.Null[string]()
	patch.Etag = graphql.Value(repox.NewULID())
	if _, err := r.Svc.Mutation.Hotel.Resource.UpdateIfMatch(ctx, id, patch, resourceql.DeleteTime.IsNull(false)); err != nil {
		if !errors.Is(err, graphql.ErrConflict) {
			return nil, mapGraphQLErr(err)
		}
		if _, err := r.get(ctx, id); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, id)
}

// Purge removes the record addressed by its resource name for good.
func (r *GraphQLHotelRepository) Purge(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "hotels"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	_, err = r.purge(ctx, id, name, true)
	return err
}

// purge removes row id, named name, for good -- unless something still
// refers to it, when it keeps the row and reports kept: when askReferrers, a
// referrer in another database or service (r.Refs), and, caught from the
// database's own refusal, a row holding a foreign key to it. A purge never
// fails, and never cascades, because of a referrer. repox.ErrNotFound when
// there is no such row.
func (r *GraphQLHotelRepository) purge(ctx context.Context, id, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "hotel.opentravel.org/Hotel", name) {
		return true, nil
	}
	err = r.remove(ctx, id)
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GraphQLHotelRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			id, err := r.rowID(ctx, m.GetName())
			if errors.Is(err, repox.ErrNotFound) {
				continue // gone since the page was read
			}
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, id, m.GetName(), true)
			switch {
			case errors.Is(err, repox.ErrNotFound):
			case err != nil:
				return res, err
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

